      "chunk_id": "text_3",
      "quote": "Guideline-based and restricted fluid resuscitation strategy in sepsis patients with heart failure: A systematic review and meta-analysis",
      "reason": "The title explicitly identifies the report as \"a systematic review and meta-analysis,\" meeting the requirement to identify the report as a systematic review."
    },
    {
      "element_id": "prisma_2020_1_e2",
      "status": "PRESENT",
      "chunk_id": "text_3",
      "quote": "Guideline-based and restricted fluid resuscitation strategy in sepsis patients with heart failure: A systematic review and meta-analysis",
      "reason": "The title names the population ('sepsis patients with heart failure') and the intervention/exposure ('guideline-based and restricted fluid resuscitation strategy'), providing key information about the main objective/review question."
    },
    {
      "element_id": "prisma_2020_1_e3",
      "status": "PRESENT",
      "chunk_id": "text_3",
      "quote": "Guideline-based and restricted fluid resuscitation strategy in sepsis patients with heart failure: A systematic review and meta-analysis",
      "reason": "The title includes the analysis method ('meta-analysis'), which is relevant supplementary information about the review's analysis approach."
